import{_ as o,l as i,o as a,c as d,v as l,p as n,x as r,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"自定义 allreduce","description":"","frontmatter":{"title":"自定义 allreduce","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/custom-allreduce.md","filePath":"llm/custom-allreduce.md","lastUpdated":1789023840000}'),u={name:"llm/custom-allreduce.md"};function A(C,e,m,h,L,_){const t=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=l('<h1 id="自定义-allreduce" tabindex="-1">自定义 allreduce <a class="header-anchor" href="#自定义-allreduce" aria-label="Permalink to &quot;自定义 allreduce&quot;">​</a></h1><div class="epigraph"><p>张量并行每层都要一次求和；通用 NCCL 为训练的大块梯度而设计，decode 上那一小条激活往往更适合走 NVLink 上的手写环形或一发多收。</p><footer>—— 对照 Megatron-LM 的层内 All-Reduce（Shoeybi 等）与 vLLM / TensorRT-LLM 针对推理短消息的自定义实现</footer></div><p><a href="/llm/kernel-autotuning">上一课</a>把单卡核调到接近屋顶。多卡 TP 下，屋顶旁边还有通信：<a href="/llm/tensor-parallel">张量并行</a>每层两次 All-Reduce（前向一次、某些切法下反向再一次；推理前向每层至少一次）。decode 的激活体积是 \\(B\\times 1\\times d\\)，相对训练梯度很小，延迟被消息启动开销主导。本课写为什么引擎会绕开通用 NCCL、自己写一层 AR；下一课才谈与 GEMM 重叠。NCCL 调参是再下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NCCL 对大块、规则、跨节点拓扑很强。推理 TP 通常在 NVLink 域内，消息小、频率高（每 token 每层）。通用路径的启动、握手与不必要的拷贝可以比有效负载还贵。缺口是一条 <em>推理专用</em> 的 All-Reduce：利用 NVLink P2P、持久工作组、甚至 CUDA Graph 捕获，把小消息延迟打下来。正确性仍是逐元素求和，与 Megatron 数学相同。</p><p>自定义实现往往假设：同机、NVLink 全连接或固定环、进程绑定不变。跨节点 TP 仍应回退 NCCL。不要把自定义 AR 写成「永远更快」。</p><p><span class="marginnote">自定义 AR 吃的是激活，不是 KV。KV 按头切在各卡本地。<a href="/llm/kv-layout">KV 布局</a>与 AR 无关，但 TP 切头要求 \\(h_{kv}\\) 能被 TP 整除，否则还要在组内复制 KV。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常见手法：各 rank 把分片写到对称显存或 IPC 映射区，按环累加再广播，或走 NVLink 的一到多。工作组常驻，避免每步重建 communicator。与采样的关系：词表并行时 logits 的归约也是小 All-Reduce，应走同一套短消息路径，且 <em>只在一处采样</em>。实现必须处理非对齐 \\(d\\)、半精度溢出（用 FP32 累加）。</p><p>测：对目标 \\(B,d\\) 画自定义 vs NCCL 延迟。交叉点通常在消息变大（大 \\(B\\) 或 prefill）时回到 NCCL。引擎应按体积分派。</p>',10)),(a(),n(p,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E8%A1%8C%E5%B9%B6%E8%A1%8C%E5%90%8E%E7%9A%84%E9%83%A8%E5%88%86%E5%92%8C%22%5D%20--%3E%20AR%7B%22%E6%B6%88%E6%81%AF%E4%BD%93%E7%A7%AF%22%7D%0A%20%20AR%20--%3E%7C%22decode%20%E7%9F%AD%22%7C%20CUS%5B%22%E8%87%AA%E5%AE%9A%E4%B9%89%20NVLink%20AR%22%5D%0A%20%20AR%20--%3E%7C%22prefill%20%E9%95%BF%22%7C%20NCCL%5B%22NCCL%22%5D%0A%20%20CUS%20--%3E%20Y2%5B%22%E5%AE%8C%E6%95%B4%E6%BF%80%E6%B4%BB%22%5D%0A%20%20NCCL%20--%3E%20Y2%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>小消息延迟 = 启动 + 传输。自定义路径砍启动、用持久映射砍握手。带宽项在 decode 上往往不是主项。这与屋顶线一致：通信强度同样可以算 FLOPs/通信字节；decode 的层内 AR 是延迟绑定。投机校验加宽 \\(n_q\\)，激活变厚，可能越过交叉点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在异构或跨节点拓扑上强行自定义。不要与 NCCL 同时各搞一套无文档的顺序，死锁风险。数值与顺序：环形累加顺序与 NCCL 树不同，半精度尾差要验收。下一课：把这次 AR 藏进 GEMM 的空隙。</p><p>出处：Shoeybi et al., Megatron-LM；推理侧以 vLLM / TensorRT-LLM 的自定义 All-Reduce 实现为准。不编造论文编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>decode 的层内 AR 是小消息、高频、NVLink 域，适合自定义路径。</li><li>大消息与跨节点回退 NCCL。</li><li>正确性仍是求和；只在一处采样。</li><li>交叉点随 \\(B\\)、\\(n_q\\) 变，要分派。</li><li>布局切的是 KV，AR 吃的是激活。</li><li>下一课：通信与计算重叠。</li><li>出处：Megatron-LM；vLLM / TensorRT-LLM 自定义 AR。</li></ul>',7))])}const T=o(u,[["render",A]]);export{N as __pageData,T as default};
